// Generated by build.js — do not edit. Rebuild with: node build.js <chrome|firefox>
// ---- keymap.js ----
// Jari: default key bindings, prefix keys, non-key defaults, a tiny event
// bus and the shared helpers used by both the content scripts and the options
// page (which loads this file first via script tags).
//
// Keys use the exact `event.key` value, optionally prefixed with modifier
// names ("ctrl+", "alt+", "meta+"). Shift is NOT part of the string — a
// capital letter is its own key ("G", "X"), so H/h and L/l are distinct.
//
// Multi-key prefixes ("go", "gu") are composed from a prefix key ("g") via
// Jari.prefixes. The dispatcher in content.js resolves a prefix before
// consulting the single-key keymap. No fixed sequences ship by default —
// every pair is user-bound from the options page.
(() => {
  const Jari = window.Jari || (window.Jari = {});

  Jari.Events = Jari.Events || {
    listeners: {},
    on(event, fn) {
      (this.listeners[event] ||= []).push(fn);
    },
    emit(event, ...args) {
      for (const fn of this.listeners[event] || []) fn(...args);
    },
  };

  Jari.keymapDefaults = {
    // Scrolling
    j: 'scrollDown',
    k: 'scrollUp',
    h: 'scrollLeft',
    l: 'scrollRight',
    G: 'scrollBottom',
    w: 'showScrollArea',
    '+': 'zoomIn',
    '-': 'zoomOut',

    // Tabs
    t: 'omnibar',
    x: 'closeTab',
    X: 'restoreTab',
    H: 'previousTab',
    L: 'nextTab',
    '<<': 'moveTabLeft',
    '>>': 'moveTabRight',

    // Window: split this tab into its own window; again, merge back.
    W: 'splitOrMergeTab',

    // History
    S: 'historyBack',
    D: 'historyForward',

    // Hints
    f: 'linkHints',
    F: 'linkHintsNewTab',
    i: 'focusInput',

    // Page navigation
    r: 'reloadTab',
    R: 'hardReload',

    // Clipboard
    Y: 'copyTitleUrl',
    p: 'pasteOpen',
    P: 'pasteOpenBackground',

    // Site-level control
    I: 'toggleIgnore',
    o: 'passthrough',
    'ctrl+alt+v': 'toggleDisabled',

    // Help
    '?': 'showHelp',

    // Two-key sequences, composed via the prefix keys (g, ;, y) below.
    // Stored like any other binding: rebindable, overridable, and visible in
    // the options table and help overlay.
    gt: 'tabSearch',
    gg: 'scrollTop',
    gu: 'goUp',
    gU: 'goToRoot',
    ge: 'editUrl',
    gs: 'cycleScrollArea',
    gS: 'resetScrollArea',
    g0: 'firstTab',
    g$: 'lastTab',
    ';e': 'openOptions',
    yf: 'linkHintsYank',
    yy: 'copyUrl',
  };

  // Prefix keys: the first key of a two-key binding ("go" = "g" then "o").
  // The pairs themselves are plain keymap entries (see keymapDefaults). Add
  // more prefix keys here without touching the dispatcher.
  Jari.prefixes = {
    g: {},
    ';': {},
    y: {},
    '<': {},
    '>': {},
  };

  // Command categories, shared by the help overlay and the options page.
  Jari.categories = [
    { id: 'scrolling', label: 'Scrolling' },
    { id: 'view', label: 'View & zoom' },
    { id: 'tabs', label: 'Tabs' },
    { id: 'tabActions', label: 'Tab actions' },
    { id: 'history', label: 'History' },
    { id: 'hints', label: 'Hints' },
    { id: 'page', label: 'Page' },
    { id: 'clipboard', label: 'Clipboard' },
    { id: 'modes', label: 'Modes' },
    { id: 'help', label: 'Help' },
  ];

  // Non-key defaults. Overridable from the options page.
  Jari.settingsDefaults = {
    scrollStep: 200,
    smoothScroll: false,
    // Rank prompt lists by fuzzy subsequence score instead of plain substring.
    fuzzyMatching: true,
    timeoutMs: 2000,
    // "o" passthrough duration: how long keys reach the page before Jari
    // takes over again (Escape exits sooner).
    passthroughMs: 3000,
  };

  // Bindings removed from the defaults after a keybind overhaul. Stripped from
  // any stored keymap so old saved configs stop showing them.
  Jari.unboundKeys = [];

  // Prefix keys ("g", ";", "y") must never double as single-key bindings —
  // the dispatcher resolves a prefix before the single-key keymap, so a lone
  // "g" binding would be shadowed and conflict with the prefix group. Stripped
  // from stored keymaps like unboundKeys, and rejected by the options-page
  // recorder.
  Jari.prefixKeys = new Set(Object.keys(Jari.prefixes || {}));

  // --- Shared helpers ------------------------------------------------------
  // Loaded by the content scripts and the options page; both must agree on
  // these so bindings and settings behave identically in each context.

  // Bare modifier keys never complete a composition or a keybinding by
  // themselves. "OS" is the Windows/Super key, "Fn" and "AltGraph" laptop
  // extras.
  Jari.modifierKeys = new Set([
    'Control',
    'Alt',
    'Shift',
    'Meta',
    'OS',
    'CapsLock',
    'NumLock',
    'ScrollLock',
    'Fn',
    'AltGraph',
  ]);

  // Canonical key string: modifiers in ctrl/alt/meta order, then the key.
  // "Shift" is deliberately absent — a capital letter is its own key.
  Jari.canonicalKey = function canonicalKey(event) {
    const parts = [];
    if (event.ctrlKey) parts.push('ctrl');
    if (event.altKey) parts.push('alt');
    if (event.metaKey) parts.push('meta');
    parts.push(event.key);
    return parts.join('+');
  };

  // Elements Jari's own overlays create. Content features must not touch
  // them: hints must not label them.
  Jari.overlaySelectors = '.jari-overlay, .jari-hint, .jari-scroll-highlight';

  // Command renames, old id -> new id. Stored keymaps may reference the old
  // names; normalizeSettings remaps them so existing bindings keep working.
  Jari.renamedCommands = {
    scrollHalfDown: 'scrollHalfPageDown',
    scrollHalfUp: 'scrollHalfPageUp',
    goParentUrl: 'goUp',
    goUrlRoot: 'goToRoot',
    pasteOpenTab: 'pasteOpen',
    pasteOpenTabBackground: 'pasteOpenBackground',
  };

  // Sanitize a raw storage blob into a complete settings object with defaults
  // filled in and invalid values dropped. Shared by the content-script
  // settings layer and the options page so both interpret stored values the
  // same way.
  Jari.normalizeSettings = function normalizeSettings(data) {
    const d = data || {};
    const storedKeymap = {};
    for (const [key, command] of Object.entries(d.keymap || {})) {
      storedKeymap[key] = Jari.renamedCommands[command] || command;
    }
    const keymap = { ...Jari.keymapDefaults, ...storedKeymap };
    for (const key of Jari.unboundKeys) delete keymap[key];
    for (const key of Jari.prefixKeys) delete keymap[key];
    return {
      keymap,
      disabledSites: Array.isArray(d.disabledSites) ? d.disabledSites : [],
      scrollStep: Number.isFinite(d.scrollStep) ? d.scrollStep : Jari.settingsDefaults.scrollStep,
      smoothScroll:
        typeof d.smoothScroll === 'boolean' ? d.smoothScroll : Jari.settingsDefaults.smoothScroll,
      fuzzyMatching:
        typeof d.fuzzyMatching === 'boolean' ? d.fuzzyMatching : Jari.settingsDefaults.fuzzyMatching,
      timeoutMs:
        Number.isFinite(d.timeoutMs) && d.timeoutMs > 0
          ? d.timeoutMs
          : Jari.settingsDefaults.timeoutMs,
      passthroughMs:
        Number.isFinite(d.passthroughMs) && d.passthroughMs > 0
          ? d.passthroughMs
          : Jari.settingsDefaults.passthroughMs,
    };
  };

  // URL helpers shared by the page-navigation commands ("gu"/"gU") and the
  // omnibar's URL-vs-search guess.
  Jari.Url = {
    parentUrlOf(href) {
      try {
        const url = new URL(href);
        let path = url.pathname;
        if (path.length > 1 && path.endsWith('/')) path = path.slice(0, -1);
        const idx = path.lastIndexOf('/');
        path = idx > 0 ? path.slice(0, idx) : '/';
        url.pathname = path;
        url.search = '';
        url.hash = '';
        return url.href;
      } catch {
        return href;
      }
    },

    rootUrlOf(href) {
      try {
        const url = new URL(href);
        url.pathname = '/';
        url.search = '';
        url.hash = '';
        return url.href;
      } catch {
        return href;
      }
    },

    isSamePath(a, b) {
      try {
        return new URL(a).pathname === new URL(b).pathname;
      } catch {
        return a === b;
      }
    },

    // A bare query that is a URL — scheme, protocol-relative, localhost, or a
    // dotted hostname (with an optional path/port). Everything else is search
    // terms. The background's normalizeUrl turns bare hosts into https.
    looksLikeUrl(text) {
      const s = text.trim();
      if (!s || /\s/.test(s)) return false;
      if (/^[a-z][a-z0-9+.-]*:\/\//i.test(s) || s.startsWith('//')) return true;
      if (/^localhost(:\d+)?(\/.*)?$/i.test(s)) return true;
      return /^[a-z0-9-]+(\.[a-z0-9-]+)+([:/?#].*)?$/i.test(s);
    },
  };

  // Fuzzy subsequence matcher for the prompt lists. Every query char must
  // appear in text in order; the returned score ranks results so consecutive
  // runs, word starts, camel-case boundaries and early positions win. Returns
  // null on no match.
  Jari.fuzzyMatch = function fuzzyMatch(query, text) {
    const q = String(query).toLowerCase();
    const t = String(text).toLowerCase();
    if (!q) return null;
    let score = 0;
    let consecutive = 0;
    let last = -1;
    const indices = [];
    for (const ch of q) {
      const i = t.indexOf(ch, last + 1);
      if (i === -1) return null;
      indices.push(i);
      if (i === last + 1) {
        consecutive += 1;
        score += 14 + consecutive; // a run scores higher the longer it is
      } else {
        consecutive = 0;
        score += 2;
        score -= (i - last) * 3; // gap penalty for skipped characters
      }
      if (i === 0 || !/[\w]/.test(t[i - 1])) score += 12; // word start
      else if (text[i] !== text[i].toLowerCase()) score += 8; // camel-case boundary
      last = i;
    }
    return { score, indices };
  };

  // Greedy column balance for the help overlay and the options keymap grid:
  // assign each category to the currently shortest column so the columns end
  // up roughly equal (a category header counts one row + one row per command).
  // byCategory: Map of category id -> array of entries; returns columns as
  // arrays of category objects from Jari.categories.
  Jari.balanceCategories = function balanceCategories(byCategory, columnCount = 3) {
    const columns = Array.from({ length: columnCount }, () => []);
    const columnRows = columns.map(() => 0);
    for (const cat of Jari.categories || []) {
      const rows = byCategory.get(cat.id);
      if (!rows) continue;
      let best = 0;
      for (let i = 1; i < columnCount; i++) {
        if (columnRows[i] < columnRows[best]) best = i;
      }
      columns[best].push(cat);
      columnRows[best] += 1 + rows.length;
    }
    return columns;
  };
})();

// ---- settings.js ----
// Jari: settings layer over chrome.storage.sync.
// Holds the user keymap, the list of per-site disabled hosts, and the
// behavior options (scroll step, smooth scrolling, timeouts).
// Emits "settingsChanged" when storage changes so live tabs react instantly.
(() => {
  const Jari = window.Jari || (window.Jari = {});

  const STORAGE_KEY = "settings";

  const state = {
    keymap: { ...Jari.keymapDefaults },
    disabledSites: [],
    scrollStep: Jari.settingsDefaults.scrollStep,
    smoothScroll: Jari.settingsDefaults.smoothScroll,
    fuzzyMatching: Jari.settingsDefaults.fuzzyMatching,
    timeoutMs: Jari.settingsDefaults.timeoutMs,
    passthroughMs: Jari.settingsDefaults.passthroughMs,
  };

  function merge(data) {
    const s = Jari.normalizeSettings(data);
    state.keymap = s.keymap;
    state.disabledSites = s.disabledSites;
    state.scrollStep = s.scrollStep;
    state.smoothScroll = s.smoothScroll;
    state.fuzzyMatching = s.fuzzyMatching;
    state.timeoutMs = s.timeoutMs;
    state.passthroughMs = s.passthroughMs;
  }

  async function load() {
    try {
      const stored = await chrome.storage.sync.get(STORAGE_KEY);
      merge(stored[STORAGE_KEY] || {});
    } catch {
      merge({});
    }
  }

  function persist() {
    return chrome.storage.sync.set({
      [STORAGE_KEY]: {
        keymap: state.keymap,
        disabledSites: state.disabledSites,
        scrollStep: state.scrollStep,
        smoothScroll: state.smoothScroll,
        fuzzyMatching: state.fuzzyMatching,
        timeoutMs: state.timeoutMs,
        passthroughMs: state.passthroughMs,
      },
    });
  }

  // Mutate the in-memory state without touching storage. The options page
  // edits this way and only writes on Save; the content script persists
  // immediately via update().
  function set(patch) {
    merge(Jari.normalizeSettings({ ...state, ...patch }));
  }

  // Mutate and persist. Awaitable so callers can report write failures.
  async function update(patch) {
    set(patch);
    await persist();
  }

  function getKeymap() {
    return state.keymap;
  }

  function isDisabled() {
    return state.disabledSites.includes(location.hostname);
  }

  function getDisabledSites() {
    return state.disabledSites.slice();
  }

  function getScrollStep() {
    return state.scrollStep;
  }

  function isSmoothScroll() {
    return state.smoothScroll;
  }

  function isFuzzyMatching() {
    return state.fuzzyMatching;
  }

  function getTimeoutMs() {
    return state.timeoutMs;
  }

  function getPassthroughMs() {
    return state.passthroughMs;
  }

  function toggleDisabled() {
    const host = location.hostname;
    const idx = state.disabledSites.indexOf(host);
    if (idx >= 0) state.disabledSites.splice(idx, 1);
    else state.disabledSites.push(host);
    persist().catch(() => {});
  }

  chrome.storage.onChanged.addListener((changes, area) => {
    if (area !== "sync" || !changes[STORAGE_KEY]) return;
    merge(changes[STORAGE_KEY].newValue || {});
    Jari.Events.emit("settingsChanged");
  });

  Jari.settings = {
    load,
    update,
    getKeymap,
    isDisabled,
    getDisabledSites,
    getScrollStep,
    isSmoothScroll,
    isFuzzyMatching,
    getTimeoutMs,
    getPassthroughMs,
    toggleDisabled,
  };
})();

// ---- ui.js ----
// Jari: shared UI helpers for content scripts.
(() => {
  const Jari = window.Jari || (window.Jari = {});

  // Promise-based wrapper around chrome.runtime.sendMessage that works with
  // the callback-style API in both Chrome and Firefox.
  function sendMessage(action, payload = {}) {
    return new Promise((resolve) => {
      try {
        chrome.runtime.sendMessage({ action, ...payload }, (response) => {
          if (chrome.runtime.lastError) return resolve(null);
          resolve(response);
        });
      } catch {
        resolve(null);
      }
    });
  }

  // Shared fixed container for the corner UI (toast, showcmd, mode pill): a
  // single flex row pinned flush to the bottom-right so the three sit side by
  // side instead of stacking. Lazy — created on first use.
  let statusStack = null;
  function statusContainer() {
    if (!statusStack) {
      statusStack = document.createElement("div");
      statusStack.className = "jari-status-stack";
      document.body.appendChild(statusStack);
    }
    return statusStack;
  }

  // A single toast element, reused: a new message replaces the old one
  // instead of stacking another pill in the row.
  let toastEl = null;
  let toastTimer = null;

  function toast(message) {
    if (!toastEl) {
      toastEl = document.createElement("div");
      toastEl.className = "jari-toast";
      statusContainer().appendChild(toastEl);
    }
    toastEl.textContent = message;
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => {
      toastEl.remove();
      toastEl = null;
    }, 1500);
  }

  // Copy text to the clipboard, with a fallback for contexts without async
  // clipboard support. Callers toast their own message.
  async function copyText(text) {
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      ta.remove();
    }
  }

  // Neovim-style showcmd readout: echoes the keys currently being composed
  // (count digits, prefix keys) in the bottom-right corner.
  let showcmdEl = null;
  let flashTimer = null;

  function showcmd(text) {
    if (!text) {
      if (showcmdEl) {
        showcmdEl.remove();
        showcmdEl = null;
      }
      return;
    }
    if (!showcmdEl) {
      showcmdEl = document.createElement("div");
      showcmdEl.className = "jari-showcmd";
      statusContainer().appendChild(showcmdEl);
    }
    showcmdEl.textContent = text;
  }

  // Show the composed key sequence for a moment after a command runs.
  function flash(text, ms = 600) {
    showcmd(text);
    clearTimeout(flashTimer);
    flashTimer = setTimeout(() => showcmd(null), ms);
  }

  Jari.sendMessage = sendMessage;
  Jari.ui = { toast, showcmd, flash, copyText, statusContainer };
})();

// ---- commands.js ----
// Jari: the command registry.
// Each command is { category, label, run, repeatable? }. category groups
// commands on the options page.
// run receives { count, event }. repeatable commands scale with the count
// prefix (e.g. "3j", "5x").
(() => {
  const Jari = window.Jari || (window.Jari = {});

  const PAGE_RATIO = 0.9;
  const HALF_RATIO = 0.5;

  // Scrolling targets the window by default; "gs"/"gS" retarget it to a
  // page's nested scroll container (or back to the window).
  function getScrollElement() {
    return Jari.Scroll.getTarget();
  }

  function scrollHeightOf(el) {
    return el === window
      ? (document.scrollingElement || document.documentElement || document.body).scrollHeight
      : el.scrollHeight;
  }

  function clientHeightOf(el) {
    return el === window ? window.innerHeight : el.clientHeight;
  }

  // Manual smooth scrolling. Holding a key fires repeated keydowns; each
  // scrollBy({ behavior: "smooth" }) cancels the previous animation, which
  // stutters. Instead, accumulate the requested distance and animate it with
  // requestAnimationFrame until it is consumed.
  let smoothState = null; // { el, x, y, rafId }

  function scrollPosOf(el) {
    return el === window
      ? { x: window.scrollX, y: window.scrollY }
      : { x: el.scrollLeft, y: el.scrollTop };
  }

  // Respect the OS-level reduced-motion preference: when set, skip the smooth
  // animation and jump instantly even if smoothScroll is enabled.
  function prefersReducedMotion() {
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }

  function smoothScrollBy(el, x, y) {
    if (smoothState === null || smoothState.el !== el) {
      smoothState = { el, x: 0, y: 0, rafId: null };
    }
    smoothState.x += x;
    smoothState.y += y;
    if (smoothState.rafId === null) {
      smoothState.rafId = requestAnimationFrame(smoothScrollStep);
    }
  }

  function smoothScrollStep() {
    if (!smoothState) return;
    smoothState.rafId = null;
    const { el } = smoothState;
    const pendingX = smoothState.x;
    const pendingY = smoothState.y;
    if (pendingX === 0 && pendingY === 0) {
      smoothState = null;
      return;
    }
    // Ease-out toward the target, capped per frame so a large backlog (a held
    // key) still scrolls at a steady, sane speed.
    const CAP = 150;
    const moveX =
      pendingX !== 0
        ? Math.sign(pendingX) * Math.max(1, Math.min(CAP, Math.round(Math.abs(pendingX) * 0.25)))
        : 0;
    const moveY =
      pendingY !== 0
        ? Math.sign(pendingY) * Math.max(1, Math.min(CAP, Math.round(Math.abs(pendingY) * 0.25)))
        : 0;

    const before = scrollPosOf(el);
    el.scrollBy({ left: moveX, top: moveY, behavior: "auto" });
    const after = scrollPosOf(el);
    const dx = after.x - before.x;
    const dy = after.y - before.y;
    // Consume what actually moved; an axis that couldn't move (scroll limit
    // reached) is dropped so the loop can end, while the other axis keeps
    // animating.
    if (dx !== 0) smoothState.x -= dx;
    else smoothState.x = 0;
    if (dy !== 0) smoothState.y -= dy;
    else smoothState.y = 0;

    smoothState.rafId = requestAnimationFrame(smoothScrollStep);
  }

  function scrollBy({ x = 0, y = 0, count = 1 }) {
    const el = getScrollElement();
    if (Jari.settings.isSmoothScroll() && !prefersReducedMotion()) {
      smoothScrollBy(el, x * count, y * count);
    } else {
      el.scrollBy({ left: x * count, top: y * count, behavior: "auto" });
    }
  }

  async function copyToClipboard(text, message) {
    await Jari.ui.copyText(text);
    Jari.ui.toast(message);
  }

  // Read the clipboard. A hidden textarea + execCommand("paste") is the
  // reliable path from a content script (needs the "clipboardRead" permission
  // in the manifest); navigator.clipboard.readText() is the fallback on
  // secure pages. The caller treats the result as a URL — background
  // normalizeUrl turns bare hostnames into https.
  function pasteClipboard() {
    const ta = document.createElement("textarea");
    ta.style.position = "fixed";
    ta.style.opacity = "0";
    document.body.appendChild(ta);
    ta.focus();
    let text = "";
    try {
      if (document.execCommand("paste")) text = ta.value.trim();
    } catch {}
    ta.remove();
    if (text) return Promise.resolve(text);
    try {
      return navigator.clipboard.readText().then((t) => t.trim()).catch(() => "");
    } catch {
      return Promise.resolve("");
    }
  }

  const commands = {
    // Scrolling
    scrollDown: { category: "scrolling", label: "Scroll down", repeatable: true, run: (c) => scrollBy({ y: Jari.settings.getScrollStep(), count: c.count }) },
    scrollUp: { category: "scrolling", label: "Scroll up", repeatable: true, run: (c) => scrollBy({ y: -Jari.settings.getScrollStep(), count: c.count }) },
    scrollLeft: { category: "scrolling", label: "Scroll left", repeatable: true, run: (c) => scrollBy({ x: -Jari.settings.getScrollStep(), count: c.count }) },
    scrollRight: { category: "scrolling", label: "Scroll right", repeatable: true, run: (c) => scrollBy({ x: Jari.settings.getScrollStep(), count: c.count }) },
    scrollTop: {
      category: "scrolling",
      label: "Scroll to top",
      run: () => {
        const el = getScrollElement();
        if (Jari.settings.isSmoothScroll() && !prefersReducedMotion()) smoothScrollBy(el, 0, -scrollPosOf(el).y);
        else el.scrollTo({ top: 0, behavior: "auto" });
      },
    },
    scrollBottom: {
      category: "scrolling",
      label: "Scroll to bottom",
      run: () => {
        const el = getScrollElement();
        const target = Math.max(0, scrollHeightOf(el) - clientHeightOf(el));
        if (Jari.settings.isSmoothScroll() && !prefersReducedMotion()) smoothScrollBy(el, 0, target - scrollPosOf(el).y);
        else el.scrollTo({ top: target, behavior: "auto" });
      },
    },
    scrollPageDown: {
      category: "scrolling",
      label: "Scroll page down",
      repeatable: true,
      run: (c) => scrollBy({ y: clientHeightOf(getScrollElement()) * PAGE_RATIO, count: c.count }),
    },
    scrollPageUp: {
      category: "scrolling",
      label: "Scroll page up",
      repeatable: true,
      run: (c) => scrollBy({ y: -clientHeightOf(getScrollElement()) * PAGE_RATIO, count: c.count }),
    },
    scrollHalfPageDown: {
      category: "scrolling",
      label: "Scroll half page down",
      repeatable: true,
      run: (c) => scrollBy({ y: clientHeightOf(getScrollElement()) * HALF_RATIO, count: c.count }),
    },
    scrollHalfPageUp: {
      category: "scrolling",
      label: "Scroll half page up",
      repeatable: true,
      run: (c) => scrollBy({ y: -clientHeightOf(getScrollElement()) * HALF_RATIO, count: c.count }),
    },
    cycleScrollArea: { category: "scrolling", label: "Cycle nested scroll areas", run: () => Jari.Scroll.cycle() },
    resetScrollArea: { category: "scrolling", label: "Reset to page scroll", run: () => Jari.Scroll.resetToGlobal() },
    showScrollArea: { category: "scrolling", label: "Show scroll area", run: () => Jari.Scroll.showHighlight() },
    zoomIn: { category: "view", label: "Zoom in", run: () => Jari.sendMessage("zoomBy", { delta: 0.1 }) },
    zoomOut: { category: "view", label: "Zoom out", run: () => Jari.sendMessage("zoomBy", { delta: -0.1 }) },

    // Tabs
    newTab: { category: "tabs", label: "New tab", run: () => Jari.sendMessage("createTab") },
    closeTab: { category: "tabs", label: "Close tab", repeatable: true, run: (c) => Jari.sendMessage("closeTab", { count: c.count }) },
    restoreTab: { category: "tabs", label: "Reopen closed tab", repeatable: true, run: (c) => Jari.sendMessage("restoreTab", { count: c.count }) },
    pasteOpen: {
      category: "tabs",
      label: "Open clipboard URL in current tab",
      run: async () => {
        const text = await pasteClipboard();
        if (!text) return Jari.ui.toast("Clipboard empty");
        const res = await Jari.sendMessage("navigate", { url: text });
        if (res && !res.ok) Jari.ui.toast("Not a URL");
      },
    },
    pasteOpenBackground: {
      category: "tabs",
      label: "Open clipboard URL in background tab",
      run: async () => {
        const text = await pasteClipboard();
        if (!text) return Jari.ui.toast("Clipboard empty");
        const res = await Jari.sendMessage("openInBackgroundTab", { url: text });
        if (res && !res.ok) Jari.ui.toast("Not a URL");
      },
    },
    previousTab: { category: "tabs", label: "Previous tab", repeatable: true, run: (c) => Jari.sendMessage("previousTab", { count: c.count }) },
    nextTab: { category: "tabs", label: "Next tab", repeatable: true, run: (c) => Jari.sendMessage("nextTab", { count: c.count }) },
    firstTab: { category: "tabs", label: "Jump to first tab", run: () => Jari.sendMessage("firstTab") },
    lastTab: { category: "tabs", label: "Jump to last tab", run: () => Jari.sendMessage("lastTab") },
    splitTab: { category: "tabActions", label: "Move tab to new window", run: () => Jari.sendMessage("splitTab") },
    splitOrMergeTab: {
      category: "tabActions",
      label: "Split tab / merge window",
      run: async () => {
        const res = await Jari.sendMessage("splitOrMerge");
        if (res && res.needMerge) Jari.Prompt.openMerge(res);
      },
    },
    moveTabLeft: { category: "tabActions", label: "Move tab left", run: () => Jari.sendMessage("moveTabLeft") },
    moveTabRight: { category: "tabActions", label: "Move tab right", run: () => Jari.sendMessage("moveTabRight") },
    duplicateTab: { category: "tabActions", label: "Duplicate tab", run: () => Jari.sendMessage("duplicateTab") },
    togglePin: { category: "tabActions", label: "Pin/unpin tab", run: () => Jari.sendMessage("togglePin") },
    toggleMute: { category: "tabActions", label: "Mute/unmute tab", run: () => Jari.sendMessage("toggleMute") },
    tabSearch: { category: "tabs", label: "Tab search", run: () => Jari.Prompt.open() },
    omnibar: { category: "tabs", label: "Open URL or search", run: () => Jari.Prompt.openOmnibar() },
    reloadTab: { category: "page", label: "Reload", run: () => Jari.sendMessage("reloadTab", { bypassCache: false }) },
    hardReload: { category: "page", label: "Reload (bypass cache)", run: () => Jari.sendMessage("reloadTab", { bypassCache: true }) },
    goUp: {
      category: "page",
      label: "Go to parent path",
      run: () => {
        const target = Jari.Url.parentUrlOf(location.href);
        if (Jari.Url.isSamePath(target, location.href)) return Jari.ui.toast("Already at root");
        Jari.sendMessage("navigate", { url: target });
      },
    },
    goToRoot: {
      category: "page",
      label: "Go to site root",
      run: () => {
        const target = Jari.Url.rootUrlOf(location.href);
        if (Jari.Url.isSamePath(target, location.href)) return Jari.ui.toast("Already at root");
        Jari.sendMessage("navigate", { url: target });
      },
    },
    editUrl: {
      category: "page",
      label: "Edit current URL",
      run: () => Jari.Prompt.openEditUrl(),
    },

    // Hints
    linkHints: { category: "hints", label: "Link hints", run: () => Jari.Hints.start("click") },
    linkHintsNewTab: { category: "hints", label: "Link hints (new tab)", run: () => Jari.Hints.start("newtab") },
    linkHintsYank: { category: "hints", label: "Copy link URL", run: () => Jari.Hints.start("yank") },
    focusInput: { category: "hints", label: "Focus input", run: () => Jari.Hints.start("focus") },

    // Page navigation
    historyBack: { category: "history", label: "Go back in history", run: () => Jari.sendMessage("historyBack") },
    historyForward: { category: "history", label: "Go forward in history", run: () => Jari.sendMessage("historyForward") },

    // Clipboard
    copyUrl: { category: "clipboard", label: "Copy URL", run: () => copyToClipboard(location.href, "Copied") },
    copyTitleUrl: { category: "clipboard", label: "Copy title + URL", run: () => copyToClipboard(`${document.title}\n${location.href}`, "Copied") },

    // Site-level control
    toggleIgnore: { category: "modes", label: "Ignore mode", run: () => Jari.Ignore.toggle() },
    passthrough: { category: "modes", label: "Passthrough keys (timed)", run: () => Jari.Passthrough.enter() },
    toggleDisabled: { category: "modes", label: "Enable/disable on this site", run: () => Jari.settings.toggleDisabled() },

    // Help & settings
    showHelp: { category: "help", label: "Show keybindings", run: () => Jari.Help.open() },
    openOptions: { category: "help", label: "Open settings", run: () => Jari.sendMessage("openOptions") },
  };

  Jari.commands = commands;
})();

// ---- scroll.js ----
// Jari: scroll-area targeting (g s / g S / w).
// Scrolling normally targets the window (the whole page). Some sites nest
// their content in their own scroll containers (chat panes, code panes,
// sidebars); "gs" cycles through the page's scrollable elements and "gS"
// returns to the global window scroll. "w" flashes a translucent wash over
// the active scroll area — labeled "current scroll area" — and it
// auto-dismisses; the same flash fires on every gs/gS switch.
(() => {
  const Jari = window.Jari || (window.Jari = {});

  // The active scroll target. null = the window (global scroll).
  let target = null;

  const HIGHLIGHT_MS = 300;

  // The active scroll target, as a scrollable element or the window. A page
  // mutation may have removed the element since it was picked — fall back to
  // the window so scrolling never targets a detached node.
  //
  // On a page whose viewport cannot scroll (a fixed app shell), the window
  // itself scrolls nothing, so the first lookup resolves the target to the
  // scroll area nearest the viewport. Without this, scrolling stays dead
  // until the user presses gs/w. The decision is made once and cached:
  // a picked area lives in `target`, a negative outcome in `resolved`.
  let resolved = false;

  function getTarget() {
    if (target !== null && !target.isConnected) {
      // A page change removed the element since it was picked — fall back to
      // the window and re-resolve on the next call.
      target = null;
      resolved = false;
    }
    if (target === null && !resolved) {
      resolved = true;
      if (!pageCanScroll()) {
        const areas = findScrollableElements();
        if (areas.length > 0) target = nearestArea(areas) || areas[0];
      }
    }
    return target === null ? window : target;
  }

  // findScrollableElements() walks the whole DOM and reads layout on every
  // call, which is the most expensive work in this module. The result only
  // changes when the DOM changes, so the scan is cached and invalidated by a
  // MutationObserver watching document.documentElement for node changes and
  // for class/style mutations that can turn an element scrollable or not.
  // Callers only read the returned array, so returning the cache directly is
  // safe.
  let scanEpoch = 0;
  let cachedEpoch = -1;
  let cachedAreas = null;

  if (typeof window.MutationObserver !== 'undefined') {
    new window.MutationObserver(() => {
      scanEpoch++;
    }).observe(document.documentElement, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['class', 'style'],
    });
  }

  // Elements that can actually scroll in either axis: overflow allows it and
  // the content overflows the box. Form fields (textarea/select/input) are
  // their own scrollable widgets, not page scroll areas, so they are skipped.
  // The html/body pair is the document's own scroll root — that is the
  // "global" target, so it is skipped too. Jari's overlays are excluded.
  function findScrollableElements() {
    if (cachedEpoch === scanEpoch && cachedAreas) return cachedAreas;
    cachedEpoch = scanEpoch;
    const areas = [];
    const roots = new Set([document.documentElement, document.body]);
    for (const el of document.querySelectorAll('*')) {
      if (roots.has(el)) continue;
      if (el.closest(Jari.overlaySelectors)) continue;
      const tag = el.tagName;
      if (tag === 'TEXTAREA' || tag === 'SELECT' || tag === 'INPUT') continue;
      if (el.clientHeight < 16 && el.clientWidth < 16) continue;
      const canY = el.scrollHeight > el.clientHeight + 1;
      const canX = el.scrollWidth > el.clientWidth + 1;
      if (!canY && !canX) continue;
      const style = window.getComputedStyle(el);
      const overflowY = style.overflowY;
      const overflowX = style.overflowX;
      const scrollableY =
        (overflowY === 'auto' || overflowY === 'scroll' || overflowY === 'overlay') && canY;
      const scrollableX =
        (overflowX === 'auto' || overflowX === 'scroll' || overflowX === 'overlay') && canX;
      if (scrollableY || scrollableX) areas.push(el);
    }
    cachedAreas = areas;
    return areas;
  }

  // The page itself can scroll (the document's scroll root overflows AND is
  // allowed to scroll). Many app pages set html/body { overflow: hidden } —
  // the content then overflows in measurements but the viewport cannot
  // scroll, so those pages have no global scroll stop. When the scroll
  // root's overflow is visible, the body's overflow applies to the viewport
  // instead.
  function pageCanScroll() {
    const el = document.scrollingElement || document.documentElement;
    if (!el || el.scrollHeight <= el.clientHeight + 1) return false;
    const y = window.getComputedStyle(el).overflowY;
    if (y === 'hidden' || y === 'clip') return false;
    if (y === 'visible' && document.body) {
      const bodyY = window.getComputedStyle(document.body).overflowY;
      if (bodyY === 'hidden' || bodyY === 'clip') return false;
    }
    return true;
  }

  // Nearest scroll area to the viewport center — used to pick the starting
  // point on pages without global scroll, so cycling begins where the user
  // is looking instead of at the first match in document order.
  function nearestArea(areas) {
    const cx = window.innerWidth / 2;
    const cy = window.innerHeight / 2;
    let best = null;
    let bestDist = Infinity;
    for (const el of areas) {
      const r = el.getBoundingClientRect();
      const d = Math.hypot(r.left + r.width / 2 - cx, r.top + r.height / 2 - cy);
      if (d < bestDist) {
        bestDist = d;
        best = el;
      }
    }
    return best;
  }

  // "gs": move to the next stop, wrapping around. The rotation includes the
  // window (global scroll) only when the page itself can scroll — a global
  // stop on a fixed page would scroll nothing. From the last stop the cycle
  // wraps back to the top (global or the nearest area).
  function cycle() {
    const areas = findScrollableElements();
    const pageScrolls = pageCanScroll();
    const stops = pageScrolls ? [null, ...areas] : areas;
    if (stops.length === 0) {
      target = null;
      Jari.ui.toast('No scroll areas');
      return;
    }
    const idx = stops.indexOf(target);
    if (idx === -1) {
      // Current target is not in the rotation: global on a page that cannot
      // scroll, or a detached element. Land on the nearest area, or on
      // global when the page itself scrolls.
      target = pageScrolls ? null : nearestArea(areas) || areas[0];
    } else if (pageScrolls && idx === 0) {
      // Leaving global: skip the first match in document order and go
      // straight to the area nearest the viewport — the one the user is
      // looking at.
      target = nearestArea(areas) || areas[0] || null;
    } else {
      target = stops[(idx + 1) % stops.length];
    }
    showHighlight();
  }

  // "gS": back to the global window scroll; on a page that cannot scroll,
  // there is nothing global to return to, so land on the nearest area.
  function resetToGlobal() {
    if (pageCanScroll()) {
      target = null;
    } else {
      const areas = findScrollableElements();
      if (areas.length === 0) {
        target = null;
        Jari.ui.toast('No scroll areas');
        return;
      }
      target = nearestArea(areas) || areas[0];
    }
    showHighlight();
  }

  // "w" (and every gs/gS switch): paint a translucent wash over the active
  // scroll area with a "current scroll area" label, then auto-dismiss.
  let highlightEl = null;
  let highlightTimer = null;

  function showHighlight() {
    let area = getTarget();
    if (area === window && !pageCanScroll()) {
      // The page has no global scroll, so there is nothing to highlight at
      // the window level. Pick the nearest area instead — that is the one
      // scrolling commands will act on. If nothing on the page scrolls,
      // show nothing.
      const areas = findScrollableElements();
      if (areas.length === 0) return;
      target = nearestArea(areas) || areas[0];
      area = target;
    }
    const rect =
      area === window
        ? { left: 0, top: 0, width: window.innerWidth, height: window.innerHeight }
        : area.getBoundingClientRect();

    clearTimeout(highlightTimer);
    if (highlightEl) highlightEl.remove();

    const el = document.createElement('div');
    el.className = 'jari-scroll-highlight';
    el.style.left = rect.left + 'px';
    el.style.top = rect.top + 'px';
    el.style.width = rect.width + 'px';
    el.style.height = rect.height + 'px';
    const label = document.createElement('span');
    label.className = 'jari-scroll-highlight-label';
    label.textContent = area === window ? 'global scroll' : 'current scroll area';
    el.appendChild(label);
    document.body.appendChild(el);
    highlightEl = el;
    highlightTimer = setTimeout(() => {
      if (highlightEl === el) {
        highlightEl.remove();
        highlightEl = null;
      }
    }, HIGHLIGHT_MS);
  }

  Jari.Scroll = { getTarget, cycle, resetToGlobal, showHighlight };
})();

// ---- hints.js ----
// Jari: link-hint mode (f / i).
// Overlays a letter label on visible clickable/input elements; typing the
// label resolves it. Modes:
//   click  - activate the element (same tab)
//   newtab - open anchors in a background tab, otherwise click
//   yank   - copy the link URL to the clipboard (yf)
//   focus  - focus inputs; auto-focuses when exactly one match exists
(() => {
  const Jari = window.Jari || (window.Jari = {});

  const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

  // Broad selector of "things you can click". Includes ARIA roles, inline
  // onclick handlers, and form controls; hidden inputs are excluded.
  const CLICKABLE_SELECTOR = [
    "a[href]",
    "area[href]",
    "button",
    "summary",
    "input:not([type='hidden'])",
    "select",
    "textarea",
    "[contenteditable='true']",
    "[role='button']",
    "[role='link']",
    "[role='menuitem']",
    "[role='tab']",
    "[role='checkbox']",
    "[role='radio']",
    "[role='switch']",
    "[role='option']",
    "[role='combobox']",
    "[onclick]",
  ].join(",");

  // Text-entry targets for focus mode ("i"): text-like inputs, textarea and
  // editable elements. Radio/checkbox/button/file/color/range are excluded.
  const TEXT_INPUT_TYPES = [
    "text",
    "search",
    "url",
    "tel",
    "email",
    "password",
    "number",
    "date",
    "datetime-local",
    "month",
    "week",
    "time",
  ];
  const FOCUS_SELECTOR = [
    `input:not([type]), input[type="${TEXT_INPUT_TYPES.join('"], input[type="')}"]`,
    "textarea",
    "[contenteditable='true']",
    "[contenteditable='plaintext-only']",
    "[role='textbox']",
    "[role='searchbox']",
    "[role='combobox']",
    "[role='spinbutton']",
  ].join(",");

  // Focus a text target with the caret at the end of its content — "i" should
  // drop you at the end of the line, not the start. Inputs/textarea use the
  // selection API; editable elements get a collapsed range at the end.
  // Browsers apply their own focus default (caret at start) after a
  // programmatic focus, and some sites re-place the caret in focus or
  // autocomplete handlers — so placement is retried until it sticks.
  function placeCaretAtEnd(el) {
    if (el.tagName === "TEXTAREA" || el.tagName === "INPUT") {
      try {
        const len = el.value ? el.value.length : 0;
        el.setSelectionRange(len, len);
      } catch {
        // Some input types (number, date, ...) reject selection ranges.
      }
      return;
    }
    try {
      const sel = window.getSelection();
      const range = document.createRange();
      range.selectNodeContents(el);
      range.collapse(false);
      sel.removeAllRanges();
      sel.addRange(range);
    } catch {
      // Not a real text entry (custom widget); focusing is all we can do.
    }
  }

  function focusAndPlaceCaret(el) {
    el.focus();
    // Place the caret immediately, then again across a window of ticks:
    // Chrome finalizes its focus default selection after the keydown, and
    // page handlers (React, autocomplete) can re-place the caret even later.
    // Each attempt re-verifies the element still owns focus; a fixed shot
    // count stops early so a page that keeps fighting the caret wins in the
    // end rather than Jari re-placing forever.
    const shots = [0, 16, 32, 64, 128, 256];
    for (const delay of shots) {
      setTimeout(() => {
        if (document.activeElement !== el) return;
        placeCaretAtEnd(el);
      }, delay);
    }
  }

  const MODES = {
    click: { selector: CLICKABLE_SELECTOR, activate: (el) => el.click() },
    newtab: { selector: CLICKABLE_SELECTOR, activate: openInNewTab },
    yank: { selector: CLICKABLE_SELECTOR, activate: yankLink },
    focus: { selector: FOCUS_SELECTOR, activate: focusAndPlaceCaret },
  };

  let mode = null;
  let labels = new Map(); // hint label -> target element
  let overlays = new Map(); // hint label -> overlay element
  let typed = "";

  function isActive() {
    return mode !== null;
  }

  function start(nextMode) {
    const config = MODES[nextMode];
    if (!config) return;
    cancel();

    const elements = topLevelElements(
      Array.from(document.querySelectorAll(config.selector)).filter(isInteractive),
    );
    if (nextMode === "focus" && elements.length === 1) {
      focusAndPlaceCaret(elements[0]);
      return;
    }
    if (elements.length === 0) {
      Jari.ui.toast("No matches");
      return;
    }

    mode = nextMode;
    // Multiple focus targets: hint labels appear on each input so the user
    // can pick one; tell them the hints are up.
    if (nextMode === "focus") {
      Jari.ui.toast(`${elements.length} inputs — pick one`);
    }
    const hintLabels = generateLabels(elements.length);
    elements.forEach((el, i) => {
      const label = hintLabels[i];
      labels.set(label, el);
      overlays.set(label, createHintOverlay(label, el));
    });
  }

  // An element must be on-screen and genuinely interactive: not disabled,
  // not hidden, and not an anchor without a usable href.
  function isInteractive(el) {
    if (el.disabled || el.getAttribute("aria-disabled") === "true") return false;
    if (el.closest(Jari.overlaySelectors)) return false;
    if (el.tagName === "A" || el.tagName === "AREA") {
      const href = el.getAttribute("href");
      if (href === null || href.trim() === "") return false;
    }
    return isVisible(el);
  }

  function isVisible(el) {
    const rect = el.getBoundingClientRect();
    const vw = window.innerWidth || document.documentElement.clientWidth;
    const vh = window.innerHeight || document.documentElement.clientHeight;
    if (rect.width <= 0 || rect.height <= 0) return false;
    // Must be fully inside the viewport.
    if (rect.top < 0 || rect.left < 0 || rect.bottom > vh || rect.right > vw) return false;

    // Walk up the tree: an ancestor can hide the whole subtree even when the
    // element still reports a non-zero rect — e.g. custom-styled radios are
    // often opacity:0, or carousel slides are visibility:hidden.
    let node = el;
    while (node && node.nodeType === Node.ELEMENT_NODE) {
      if (node.hasAttribute("hidden")) return false;
      const style = window.getComputedStyle(node);
      if (style.display === "none" || style.visibility === "hidden") return false;
      if (parseFloat(style.opacity) === 0) return false;
      node = node.parentElement;
    }
    return true;
  }

  // Drop nested matches: if an element sits inside another matched element,
  // only keep the outermost one so hints don't pile up on the same spot
  // (e.g. <a><button>x</button></a>).
  function topLevelElements(elements) {
    const set = new Set(elements);
    return elements.filter((el) => {
      let parent = el.parentElement;
      while (parent) {
        if (set.has(parent)) return false;
        parent = parent.parentElement;
      }
      return true;
    });
  }

  // Always two characters (AA, AB, ... ZZ). Past 676 matches it grows to
  // three characters and beyond, so labels never duplicate.
  function generateLabels(count) {
    const n = ALPHABET.length;
    const labels = [];
    let i = 0;
    let length = 2;
    while (i < count) {
      const combos = Math.pow(n, length);
      for (let k = 0; k < combos && i < count; k++, i++) {
        labels.push(toBase26(k, length));
      }
      length++;
    }
    return labels;
  }

  function toBase26(value, length) {
    let s = "";
    for (let p = 0; p < length; p++) {
      s = ALPHABET[value % 26] + s;
      value = Math.floor(value / 26);
    }
    return s;
  }

  function createHintOverlay(label, el) {
    const rect = el.getBoundingClientRect();
    const box = document.createElement("div");
    box.className = "jari-hint";
    // One span per character so updateHighlight can mute the typed prefix.
    for (const ch of label) {
      const span = document.createElement("span");
      span.textContent = ch;
      box.appendChild(span);
    }
    box.style.left = window.scrollX + rect.left + "px";
    box.style.top = window.scrollY + rect.top + "px";
    document.body.appendChild(box);
    return box;
  }

  function openInNewTab(el) {
    const href = el.href || el.getAttribute?.("href");
    // Only hand web-ish URLs to the background. Anything else (javascript:,
    // data:, mailto:, ...) is a same-tab click, which the site itself offers.
    if (href && /^(https?:|file:|about:)/i.test(href)) {
      Jari.sendMessage("openInBackgroundTab", { url: href });
    } else {
      el.click();
    }
  }

  function yankLink(el) {
    const href = el.href || el.getAttribute?.("href");
    if (href) {
      Jari.ui.copyText(href).then(() => Jari.ui.toast("Copied"));
    }
  }

  function onKeyDown(event) {
    event.preventDefault();
    event.stopImmediatePropagation();

    if (event.key === "Escape") {
      cancel();
      return;
    }

    typed += event.key.toLowerCase();

    let exact = null;
    let partial = 0;
    for (const label of labels.keys()) {
      const lower = label.toLowerCase();
      if (lower === typed) exact = label;
      else if (lower.startsWith(typed)) partial++;
    }

    if (exact && partial === 0) {
      MODES[mode].activate(labels.get(exact));
      cancel();
      return;
    }
    if (!exact && partial === 0) {
      typed = "";
    }
    updateHighlight();
  }

  function updateHighlight() {
    for (const [label, box] of overlays) {
      const matches = label.toLowerCase().startsWith(typed);
      box.classList.toggle("jari-hint-dim", !matches);
      for (let i = 0; i < box.children.length; i++) {
        box.children[i].classList.toggle("muted", matches && i < typed.length);
      }
    }
  }

  function cancel() {
    for (const box of overlays.values()) box.remove();
    overlays.clear();
    labels.clear();
    typed = "";
    mode = null;
  }

  Jari.Hints = { start, cancel, onKeyDown, isActive };
})();

// ---- prompt.js ----
// Jari: the prompt overlay — a filterable list owned by a search box.
// "gt" (tab search) lists the open tabs: typing filters by title/URL, arrows
// move the selection, Enter activates, Escape closes.
//
// "t" (omnibar) reuses the same overlay to open a URL or search: the first
// row is the typed query (opened as a URL when it looks like one, otherwise
// searched with the default engine), below it come autocomplete matches from
// the browser (history, bookmarks, open tabs).
//
// "ge" edits the current page URL: the same omnibar prefilled with the
// current URL, and Enter navigates this tab instead of opening a new one.
//
// The overlay also serves as the merge picker for splitOrMergeTab: in a
// single-tab window it lists the tabs of the other windows and Enter moves
// this tab into the chosen one. Each feature is a mode over the one overlay.
(() => {
  const Jari = window.Jari || (window.Jari = {});

  let active = false;
  let overlay = null;
  let inputEl = null;
  let listEl = null;
  let tabs = [];
  let filtered = [];
  let selected = 0;
  let query = ""; // current filter text, used for match highlighting
  let mode = "tabs"; // "tabs" | "merge" | "open" | "edit"
  let suggestSeq = 0; // invalidates in-flight suggestion fetches
  let suggestTimer = null;

  function isActive() {
    return active;
  }

  async function open() {
    if (active) return;
    tabs = (await Jari.sendMessage("listTabs")) || [];
    if (tabs.length === 0) return;
    mode = "tabs";
    active = true;
    render("Tabs", "Search tabs...");
  }

  // "t": open a URL or search. The omnibar needs no initial data — the list
  // is built from the typed query as it comes in.
  function openOmnibar() {
    if (active) return;
    tabs = [];
    mode = "open";
    active = true;
    render("Open", "Search or type URL");
  }

  // "ge": edit the current page URL. Same omnibar as "t", but prefilled with
  // the current URL and Enter navigates this tab instead of opening a new one.
  function openEditUrl() {
    if (active) return;
    tabs = [];
    mode = "edit";
    active = true;
    render("Edit URL", "Search or type URL");
    inputEl.value = location.href;
    handleOpenInput(inputEl.value);
  }

  // Merge picker: entries are the OTHER windows (title = active tab, subtitle
  // = tab count); Enter moves this tab into the picked window.
  function openMerge(data) {
    if (active) return;
    tabs = (data && data.tabs) || [];
    mode = "merge";
    active = true;
    render("Merge into", "Choose a window...");
  }

  // Omnibar input: row 0 is always the typed query — labeled as an open or a
  // search depending on looksLikeUrl — and the suggestions arrive async,
  // debounced, replacing that row's list. A stale response (query changed or
  // overlay closed) is dropped via suggestSeq.
  function handleOpenInput(queryText) {
    const q = queryText.trim();
    query = q;
    if (!q) {
      clearTimeout(suggestTimer);
      suggestSeq++;
      filtered = [];
      selected = 0;
      renderList();
      return;
    }
    const row = Jari.Url.looksLikeUrl(q)
      ? { kind: "url", title: q, url: q }
      : { kind: "search", title: q, url: null };
    filtered = [row];
    selected = 0;
    renderList();
    clearTimeout(suggestTimer);
    const seq = ++suggestSeq;
    suggestTimer = setTimeout(async () => {
      if (!active || seq !== suggestSeq) return;
      const res = (await Jari.sendMessage("suggest", { query: q })) || [];
      if (!active || seq !== suggestSeq) return;
      const fuzzy = Jari.settings.isFuzzyMatching();
      const suggestions = res
        .map((r) => {
          const hay = r.title + " " + (r.url || "");
          const match = fuzzy
            ? Jari.fuzzyMatch(q, hay)
            : hay.toLowerCase().includes(q)
              ? { score: 0, indices: null }
              : null;
          return { kind: "suggestion", title: r.title, url: r.url, match };
        })
        .filter((r) => r.match)
        .sort((a, b) => (fuzzy ? b.match.score - a.match.score : 0));
      filtered = [row, ...suggestions];
      selected = 0;
      renderList();
    }, 130);
  }

  // Rank a list against the query; entries that don't match at all are
  // dropped. With fuzzy matching off this falls back to a plain substring
  // filter that keeps the original order.
  function rankTabs(q, list) {
    const fuzzy = Jari.settings.isFuzzyMatching();
    return list
      .map((item) => {
        const hay = item.title + " " + (item.url || "");
        const match = fuzzy
          ? Jari.fuzzyMatch(q, hay)
          : hay.toLowerCase().includes(q)
            ? { score: 0, indices: null }
            : null;
        return { item, match };
      })
      .filter((x) => x.match)
      .sort((a, b) => (fuzzy ? b.match.score - a.match.score : 0))
      .map((x) => x.item);
  }

  function render(title, placeholder) {
    overlay = document.createElement("div");
    overlay.className = "jari-overlay jari-prompt";

    inputEl = document.createElement("input");
    inputEl.type = "text";
    inputEl.placeholder = placeholder;
    inputEl.addEventListener("input", () => {
      const q = inputEl.value.trim();
      query = q;
      if (mode === "open" || mode === "edit") {
        handleOpenInput(q);
      } else {
        filtered = q ? rankTabs(q, tabs) : tabs;
        selected = 0;
        renderList();
      }
    });

    listEl = document.createElement("ul");
    listEl.className = "jari-prompt-list";

    const header = document.createElement("div");
    header.className = "jari-prompt-header";
    header.textContent = title;

    overlay.appendChild(listEl);
    overlay.appendChild(header);
    overlay.appendChild(inputEl);
    document.body.appendChild(overlay);

    filtered = tabs;
    renderList();
    inputEl.focus();
  }

  // Fill a span with text, wrapping the fuzzy-matched characters in a
  // .jari-match element. indices come from fuzzyMatch against the same text.
  function renderText(el, text, indices) {
    if (!indices || indices.length === 0) {
      el.textContent = text;
      return;
    }
    const matched = new Set(indices);
    const frag = document.createDocumentFragment();
    let run = "";
    for (let i = 0; i < text.length; i++) {
      if (matched.has(i)) {
        if (run) {
          frag.appendChild(document.createTextNode(run));
          run = "";
        }
        const mark = document.createElement("span");
        mark.className = "jari-match";
        mark.textContent = text[i];
        frag.appendChild(mark);
      } else {
        run += text[i];
      }
    }
    if (run) frag.appendChild(document.createTextNode(run));
    el.appendChild(frag);
  }

  function renderList() {
    if (mode === "open" || mode === "edit") {
      listEl.textContent = "";
      for (const row of filtered.slice(0, 50)) {
        const li = document.createElement("li");
        const title = document.createElement("span");
        title.className = "title";
        const titleText =
          row.kind === "search"
            ? `Search for "${row.title}"`
            : row.kind === "url"
              ? `Open ${row.title}`
              : row.title || "(untitled)";
        const url = document.createElement("span");
        url.className = "url";
        const urlText = row.kind === "suggestion" ? row.url || "" : "";
        // Only suggestion rows get match highlighting; the typed-query row
        // is the query itself and would look odd. Highlighting requires
        // fuzzy matching — substring mode renders plain text.
        const highlight = row.kind === "suggestion" && query && Jari.settings.isFuzzyMatching();
        if (highlight) {
          renderText(title, titleText, (Jari.fuzzyMatch(query, titleText) || {}).indices);
          renderText(url, urlText, (Jari.fuzzyMatch(query, urlText) || {}).indices);
        } else {
          title.textContent = titleText;
          url.textContent = urlText;
        }
        li.appendChild(title);
        li.appendChild(url);
        listEl.appendChild(li);
      }
      highlight();
      return;
    }

    listEl.textContent = "";
    // Label windows #1, #2, ... in order of first appearance so tabs from
    // different windows are distinguishable in the list.
    const winLabels = new Map();
    let winIndex = 0;
    const rows = filtered.slice(0, 50);
    for (const tab of rows) {
      if (!winLabels.has(tab.windowId)) winLabels.set(tab.windowId, ++winIndex);
    }
    for (const tab of rows) {
      const li = document.createElement("li");
      const win = document.createElement("span");
      win.className = "jari-win-tag";
      win.textContent = "#" + winLabels.get(tab.windowId);
      const title = document.createElement("span");
      title.className = "title";
      const titleText = tab.title || "(untitled)";
      const url = document.createElement("span");
      url.className = "url";
      const urlText = tab.url || "";
      if (query && Jari.settings.isFuzzyMatching()) {
        renderText(title, titleText, (Jari.fuzzyMatch(query, titleText) || {}).indices);
        renderText(url, urlText, (Jari.fuzzyMatch(query, urlText) || {}).indices);
      } else {
        title.textContent = titleText;
        url.textContent = urlText;
      }
      li.appendChild(win);
      li.appendChild(title);
      li.appendChild(url);
      listEl.appendChild(li);
    }
    highlight();
  }

  function highlight() {
    Array.from(listEl.children).forEach((li, i) => li.classList.toggle("selected", i === selected));
    const el = listEl.children[selected];
    if (el) el.scrollIntoView({ block: "nearest" });
  }

  function move(delta) {
    if (filtered.length === 0) return;
    selected = (selected + delta + filtered.length) % filtered.length;
    highlight();
  }

  // Capture-phase key handler. The search box owns printable keys; Escape,
  // Enter, Tab and the arrow keys are intercepted here and stopped so the
  // page never sees them.
  function onKeyDown(event) {
    const inInput = document.activeElement === inputEl;
    if (inInput) {
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopImmediatePropagation();
        close();
      } else if (event.key === "Enter") {
        event.preventDefault();
        event.stopImmediatePropagation();
        activate();
      } else if (event.key === "Tab") {
        event.preventDefault();
        event.stopImmediatePropagation();
        move(event.shiftKey ? -1 : 1);
      } else if (event.key === "ArrowDown") {
        event.preventDefault();
        event.stopImmediatePropagation();
        move(1);
      } else if (event.key === "ArrowUp") {
        event.preventDefault();
        event.stopImmediatePropagation();
        move(-1);
      }
      return;
    }
    if (event.key === "Escape" || event.key === "Enter") {
      event.preventDefault();
      event.stopImmediatePropagation();
      close();
    } else if (event.key === "Tab") {
      event.preventDefault();
      event.stopImmediatePropagation();
      move(event.shiftKey ? -1 : 1);
    }
  }

  function activate() {
    const item = filtered[selected];
    if (!item) {
      // Nothing selected: in the omnibar an empty query still opens a blank
      // new tab, preserving the old "t" behavior.
      if (mode === "open" && !inputEl.value.trim()) Jari.sendMessage("createTab");
      close();
      return;
    }
    if (mode === "merge") {
      // Merge mode: entries are windows; the background moves this tab into
      // the picked window and focuses it there.
      Jari.sendMessage("mergeTab", { targetWindowId: item.windowId });
    } else if (mode === "open" || mode === "edit") {
      // "t" opens a new tab; "ge" edits the current page, so it navigates
      // this tab instead.
      if (item.kind === "search") Jari.sendMessage("search", { query: inputEl.value, newTab: mode === "open" });
      else if (item.url) Jari.sendMessage(mode === "open" ? "createTab" : "navigate", { url: item.url });
    } else {
      Jari.sendMessage("activateTab", { id: item.id });
    }
    close();
  }

  function close() {
    clearTimeout(suggestTimer);
    suggestSeq++;
    if (overlay) {
      overlay.remove();
      overlay = null;
    }
    inputEl = null;
    listEl = null;
    tabs = [];
    filtered = [];
    selected = 0;
    query = "";
    mode = "tabs";
    active = false;
  }

  Jari.Prompt = { open, openOmnibar, openEditUrl, openMerge, close, onKeyDown, isActive };
})();

// ---- help.js ----
// Jari: keybinding help overlay (?).
// Categorized three-column modal listing every bound key and its command.
// Rendered from the live keymap, so rebinds are reflected immediately.
// On open the overlay takes focus and the help list owns the scroll:
// j/k, G and ctrl+d/u/f/b move through it.
(() => {
  const Jari = window.Jari || (window.Jari = {});

  const STEP = 50;
  const COLUMNS = 3;

  let active = false;
  let overlay = null;
  let listEl = null;
  let gPending = false;

  function isActive() {
    return active;
  }

  function open() {
    if (active) return;
    active = true;
    render();
    // Give the overlay focus so the list owns the scroll (j/k etc.). The
    // focus ring is suppressed in CSS — the modal must not show an outline.
    overlay.tabIndex = -1;
    overlay.focus();
  }

  function render() {
    overlay = document.createElement('div');
    overlay.className = 'jari-overlay jari-help';

    const title = document.createElement('div');
    title.className = 'jari-help-title';
    title.textContent = 'Jari keybindings';
    overlay.appendChild(title);

    // Collect every binding: single keys and two-key pairs from the keymap.
    const byCommand = new Map();
    for (const [key, commandName] of Object.entries(Jari.settings.getKeymap())) {
      byCommand.set(commandName, key);
    }

    const byCategory = new Map();
    for (const [commandName, key] of byCommand) {
      const cmd = Jari.commands[commandName];
      if (!cmd) continue;
      const id = cmd.category || 'other';
      if (!byCategory.has(id)) byCategory.set(id, []);
      byCategory.get(id).push({ key, label: cmd.label });
    }

    // Split the categories across three columns, keeping each category whole
    // and balancing by row count (category header + one row per command).
    const columns = Jari.balanceCategories(byCategory, COLUMNS);

    listEl = document.createElement('div');
    listEl.className = 'jari-help-list';
    const grid = document.createElement('div');
    grid.className = 'jari-help-columns';
    for (const col of columns) {
      const colEl = document.createElement('div');
      colEl.className = 'jari-help-column';
      for (const cat of col) colEl.appendChild(buildCategoryTable(cat, byCategory.get(cat.id)));
      grid.appendChild(colEl);
    }
    listEl.appendChild(grid);
    overlay.appendChild(listEl);

    const footer = document.createElement('div');
    footer.className = 'jari-help-footer';
    const hint = document.createElement('span');
    hint.textContent = 'j/k scroll | 0-9 count | esc close';
    footer.appendChild(hint);
    overlay.appendChild(footer);

    document.body.appendChild(overlay);
  }

  function buildCategoryTable(cat, rows) {
    const table = document.createElement('table');
    const tbody = document.createElement('tbody');

    const headerRow = document.createElement('tr');
    headerRow.className = 'jari-help-cat-header';
    const th = document.createElement('th');
    th.colSpan = 2;
    th.textContent = cat.label;
    headerRow.appendChild(th);
    tbody.appendChild(headerRow);

    for (const { key, label } of rows) {
      const tr = document.createElement('tr');
      const keyTd = document.createElement('td');
      keyTd.className = 'jari-help-key';
      keyTd.textContent = key;
      const labelTd = document.createElement('td');
      labelTd.className = 'jari-help-label';
      labelTd.textContent = label;
      tr.appendChild(keyTd);
      tr.appendChild(labelTd);
      tbody.appendChild(tr);
    }

    table.appendChild(tbody);
    return table;
  }

  function onKeyDown(event) {
    event.preventDefault();
    event.stopImmediatePropagation();
    if (event.key === 'Escape') {
      close();
      return;
    }
    if (event.key === 'g') {
      gPending = true;
      return;
    }
    if (gPending) {
      gPending = false;
      if (event.key === 'g') listEl.scrollTo(0, 0);
      return;
    }
    if (event.ctrlKey) {
      if (event.key === 'd') listEl.scrollBy(0, listEl.clientHeight * 0.5);
      else if (event.key === 'u') listEl.scrollBy(0, -listEl.clientHeight * 0.5);
      else if (event.key === 'f') listEl.scrollBy(0, listEl.clientHeight * 0.9);
      else if (event.key === 'b') listEl.scrollBy(0, -listEl.clientHeight * 0.9);
      return;
    }
    switch (event.key) {
      case 'G':
        listEl.scrollTo(0, listEl.scrollHeight);
        break;
      case 'j':
      case 'ArrowDown':
        listEl.scrollBy(0, STEP);
        break;
      case 'k':
      case 'ArrowUp':
        listEl.scrollBy(0, -STEP);
        break;
    }
  }

  function close() {
    if (overlay) {
      overlay.remove();
      overlay = null;
    }
    listEl = null;
    gPending = false;
    active = false;
  }

  Jari.Help = { open, close, onKeyDown, isActive };
})();

// ---- content.js ----
// Jari: content-script entry point.
// Boots settings and installs the capture-phase keydown dispatcher that
// routes keys to active modes (hints/prompt), the count prefix, the
// "g" prefix, and the user keymap. A Neovim-style showcmd
// readout echoes counts and prefix keys while they are being composed; an
// inactivity timeout drops the composition if it is never completed.
//
// "I" toggles ignore mode: Jari stops reacting to every key (except the
// toggle itself) until it is pressed again, with a persistent status pill.
// "o" enters passthrough mode: every key reaches the page until the timeout
// expires or Escape is pressed, with a transient status pill.
(() => {
  const Jari = window.Jari || (window.Jari = {});

  let pendingCount = '';
  let pendingPrefix = null;
  let typedSeq = '';
  let timer = null;
  let ignoreMode = false;
  let passthroughMode = false;
  let passthroughTimer = null;
  const pills = {}; // mode name -> pill element

  // The user stopped mid-composition (Escape, dead key, ignore toggle, or
  // inactivity timeout): drop count/prefix state and the echo.
  function clearPending() {
    pendingCount = '';
    pendingPrefix = null;
    typedSeq = '';
    Jari.ui.showcmd(null);
  }

  function restartTimer() {
    clearTimeout(timer);
    timer = setTimeout(clearPending, Jari.settings.getTimeoutMs());
  }

  function isTypingTarget(el) {
    return (
      !!el &&
      (el.tagName === 'INPUT' ||
        el.tagName === 'TEXTAREA' ||
        el.tagName === 'SELECT' ||
        el.isContentEditable ||
        el.getAttribute('role') === 'textbox')
    );
  }

  // A command consumes its key: preventDefault stops the browser default
  // action and stopImmediatePropagation (capture phase, window) keeps the
  // keydown from reaching the page or other extensions — a Jari shortcut
  // must not also trigger the site's own handler or another extension's
  // shortcut (e.g. SponsorBlock's ";" segment skip).
  function run(commandName, count, event) {
    const cmd = Jari.commands[commandName];
    if (!cmd) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    cmd.run({ count, event });
  }

  // --- Modes: ignore ("I") and passthrough ("o") --------------------------

  function setIgnore(on) {
    ignoreMode = on;
    clearPending();
    if (on) {
      // No overlay may stay open while keys pass through.
      Jari.Help.close();
      Jari.Hints.cancel();
      Jari.Prompt.close();
      showPill('ignore', 'Ignore mode');
    } else {
      hidePill('ignore');
    }
  }

  function toggleIgnore() {
    exitPassthrough();
    setIgnore(!ignoreMode);
    return ignoreMode;
  }

  // Passthrough is enter-only: while it is active the "o" key passes through
  // to the page (the user may be typing it), so only Escape — which is always
  // intercepted — and the timeout leave the mode.
  function enterPassthrough() {
    setIgnore(false);
    clearPending();
    // No overlay may stay open while keys pass through.
    Jari.Help.close();
    Jari.Hints.cancel();
    Jari.Prompt.close();
    passthroughMode = true;
    showPill('passthrough', 'Passthrough (' + Jari.settings.getPassthroughMs() + 'ms)');
    clearTimeout(passthroughTimer);
    passthroughTimer = setTimeout(exitPassthrough, Jari.settings.getPassthroughMs());
  }

  function exitPassthrough() {
    if (!passthroughMode) return;
    clearTimeout(passthroughTimer);
    passthroughMode = false;
    hidePill('passthrough');
  }

  function isFullscreen() {
    return !!document.fullscreenElement;
  }

  function showPill(name, text) {
    if (pills[name] || isFullscreen()) return;
    const el = document.createElement("div");
    el.className = "jari-pill";
    el.textContent = text;
    Jari.ui.statusContainer().appendChild(el);
    pills[name] = el;
  }

  function hidePill(name) {
    const el = pills[name];
    if (el) {
      el.remove();
      delete pills[name];
    }
  }

  // Entering fullscreen (e.g. a video) hides the pills so they never cover
  // fullscreen content; leaving fullscreen brings them back while the mode is
  // still active.
  function handleFullscreenChange() {
    if (!ignoreMode && !passthroughMode) return;
    if (isFullscreen()) {
      hidePill('ignore');
      hidePill('passthrough');
    } else {
      if (ignoreMode) showPill('ignore', 'Ignore mode');
      if (passthroughMode) showPill('passthrough', 'Passthrough');
    }
  }

  // --- Dispatcher ---------------------------------------------------------

  function handleKeydown(event) {
    // Ignore synthetic events: pages must not be able to trigger commands
    // by dispatching fake KeyboardEvents.
    if (!event.isTrusted) return;

    // A bare modifier press (Shift/Ctrl/Alt/...) is only ever a prefix of the
    // real key. Let it pass and keep any pending composition: "g" followed by
    // Shift+u must complete "gU", not cancel the prefix on the Shift keydown.
    if (Jari.modifierKeys.has(event.key)) return;

    // Passthrough mode: the page owns every key except Escape, which leaves
    // the mode early; the timeout exits it on its own.
    if (passthroughMode) {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopImmediatePropagation();
        exitPassthrough();
      }
      return;
    }

    // Ignore mode: everything passes through except the toggle itself and
    // Escape, both of which leave the mode.
    if (ignoreMode) {
      const plainI = event.key === 'I' && !event.ctrlKey && !event.altKey && !event.metaKey;
      if (plainI || event.key === 'Escape') {
        event.preventDefault();
        event.stopImmediatePropagation();
        toggleIgnore();
      }
      return;
    }

    // Disabled sites: Jari is off — only the key bound to the toggle is
    // intercepted, every other key reaches the page untouched.
    if (Jari.settings.isDisabled()) {
      const key = Jari.canonicalKey(event);
      if (Jari.settings.getKeymap()[key] === 'toggleDisabled') run('toggleDisabled', 1, event);
      return;
    }

    // Active overlays own every key; each overlay blocks the keys it
    // consumes from reaching the page.
    if (Jari.Help.isActive()) return Jari.Help.onKeyDown(event);
    if (Jari.Hints.isActive()) return Jari.Hints.onKeyDown(event);
    if (Jari.Prompt.isActive()) return Jari.Prompt.onKeyDown(event);

    const key = Jari.canonicalKey(event);

    // Resolve a pending prefix: the composed pair (e.g. "go" = "g" then "o")
    // is looked up in the keymap like any binding. Unbound pairs resolve to
    // nothing and become dead keys below. The keys stay in typedSeq so the
    // showcmd readout can echo them on execution.
    const prefixWasPending = pendingPrefix !== null;
    let commandName = null;
    if (prefixWasPending) {
      commandName = Jari.settings.getKeymap()[pendingPrefix + key] || null;
      pendingPrefix = null;
      Jari.ui.showcmd(null);
    }

    // Form fields: pass everything through except Escape (blur) and the
    // site-toggle shortcut.
    const activeEl = document.activeElement;
    if (isTypingTarget(activeEl)) {
      if (commandName === 'toggleDisabled') run(commandName, 1, event);
      else if (event.key === 'Escape') {
        event.preventDefault();
        event.stopImmediatePropagation();
        activeEl.blur();
      }
      return;
    }

    // Strict prefix composition: while a prefix is pending, a key that does
    // not complete it is a dead key, not a single-key command — "gi" must
    // never fall through to run "i", and the completing key must not reach
    // the page either (an unbound "g/" must not fire a site's "/" shortcut).
    // (Form fields were handled above, so typing in an input still passes
    // through normally.)
    if (prefixWasPending && !commandName) {
      event.preventDefault();
      event.stopImmediatePropagation();
      clearPending();
      return;
    }

    // Escape with no form field focused cancels a pending count. When idle,
    // leave Escape to the page — sites use it to close dialogs, and Jari has
    // nothing to clear.
    if (event.key === 'Escape') {
      if (pendingCount) {
        event.preventDefault();
        event.stopImmediatePropagation();
        clearPending();
      }
      return;
    }

    // Count prefix: digits 0-9 accumulate an unlimited repeat count. Only
    // when no prefix already claimed the key — "g0" is firstTab, not a count.
    if (!commandName && /^[0-9]$/.test(key)) {
      pendingCount += key;
      typedSeq += key;
      Jari.ui.showcmd(typedSeq);
      event.preventDefault();
      event.stopImmediatePropagation();
      restartTimer();
      return;
    }

    // Start a new prefix (e.g. "g", "y").
    if (!commandName && Jari.prefixes[key]) {
      pendingPrefix = key;
      typedSeq += key;
      Jari.ui.showcmd(typedSeq);
      event.preventDefault();
      event.stopImmediatePropagation();
      restartTimer();
      return;
    }

    if (!commandName) commandName = Jari.settings.getKeymap()[key];
    if (!commandName) {
      // Dead key: nothing runs, drop any composed prefix and let the page
      // see the key.
      clearPending();
      return;
    }

    const count = pendingCount ? parseInt(pendingCount, 10) : 1;
    const hadCount = pendingCount !== '';
    pendingCount = '';
    // Append the completing key even when it finished a prefix, so the echo
    // shows the full sequence ("go", "gu") rather than just the prefix.
    typedSeq += key;
    const seq = typedSeq || key;
    typedSeq = '';
    // Echo only compositions: a count or a finished prefix. Plain single-key
    // commands show nothing — the readout exists to track what is pending.
    if (hadCount || prefixWasPending) Jari.ui.flash(seq);
    restartTimer();

    run(commandName, count, event);
  }

  async function boot() {
    await Jari.settings.load();

    Jari.Events.on('settingsChanged', () => {
      if (Jari.settings.isDisabled()) {
        setIgnore(false);
        exitPassthrough();
        Jari.Help.close();
        Jari.Hints.cancel();
        Jari.Prompt.close();
      }
    });

    // window (not document) capture: the window is the outermost node in the
    // event path, so Jari claims its keys before any document-level listener
    // from the page or other extensions (e.g. SponsorBlock's ";" shortcut),
    // regardless of content-script injection order.
    window.addEventListener('keydown', handleKeydown, true);
    document.addEventListener('fullscreenchange', handleFullscreenChange);
  }

  Jari.Ignore = { toggle: toggleIgnore };
  Jari.Passthrough = { enter: enterPassthrough };

  boot();
})();
